INSERT INTO _project VALUES (17, 'โครงการ การจัดการองค์ความรู้  (Knowledge Management : KM) หลักสูตร “การเสริมสร้างความรู้และทักษะการปฏิบัติงานหน้าบัลลังก์”', '๑.	หลักการและเหตุผล\r\n		การจัดการความรู้ (Knowledge Management: KM) หมายถึง การรวบรวมองค์ความรู้ที่มีอยู่ในองค์กร ซึ่งกระจัดกระจายอยู่ในตัวบุคคล หรือเอกสารมาพัฒนาให้เป็นระบบ เพื่อให้ทุกคนในองค์กรสามารถเข้าถึงความรู้ และพัฒนาตนเองรวมทั้งปฏิบัติงานได้อย่างมีประสิทธิภาพ โดยแผนยุทธศาสตร์ศาลยุติธรรม พ.ศ.๒๕๖๕ - ๒๕๖๘ ยุทธศาสตร์ T  มีตัวชี้วัดให้ข้าราชการศาลยุติธรรมได้รับ การฝึกอบรม พัฒนาให้มีความรู้ทักษะและความสามารถในการปฏิบัติงานรองรับบทบาทภารกิจตามนโยบายประธานศาลฎีกาในการส่งเสริมระบบการจัดการองค์ความรู้  Knowledge Management  พัฒนาศักยภาพบุคลากรให้มีทักษะที่จำเป็นต่อการทำงาน ทั้งนี้ บุคลากรผู้มีหน้าที่รับผิดชอบในการปฏิบัติงานในการสนับสนุนการอำนวยความยุติธรรมและการพิจารณาพิพากษาคดี คือผู้ปฏิบัติงาน     หน้าบัลลังก์มีความบทบาทสำคัญต่อการกระบวนการพิจารณาพิพากษาและการอำนวยความยุติธรรม  เป็นอย่างมาก\r\nศาลจังหวัดอุดรธานีตระหนักถึงการพัฒนาบุคลากรให้มีทักษะในการปฏิบัติงานพัฒนาระบบงานเพื่อสนับสนุนการพิจารณาพิพากษาคดีของศาลยุติธรรมให้มีประสิทธิภาพยิ่งขึ้น จึงได้จัดทำโครงการการจัดการองค์ความรู้  หลักสูตร “การเสริมสร้างความรู้และทักษะการปฏิบัติงานหน้าบัลลังก์” ขึ้น  \r\n๒. วัตถุประสงค์\r\n๑. เพื่อพัฒนาทักษะและเสริมสร้างความรู้ความเข้าใจ เกี่ยวกับการปฏิบัติงานหน้าบัลลังก์\r\n๒. เพื่อสร้างเสริมระบบการจัดการองค์ความรู้ (Knowledge Management สามารถนำความรู้มาใช้ในการปฏิบัติงานให้เป็นไปอย่างมีประสิทธิภาพ\r\n๓. เป้าหมาย\r\nบุคลากรผู้ปฏิบัติงานหน้าบัลลังก์ และผู้ที่เกี่ยวข้อง\r\n4. ระยะเวลาดำเนินงาน\r\n		วันที่  1  มิถุนายน  2566\r\n5. วิธีดำเนินการ\r\n		1. ขออนุมัติโครงการ \r\n		2. จัดอบรมบรรยายโดยวิทยากรในหน่วยงาน\r\n		3. ประเมินผลโครงการ\r\n		4. รายงานผลโครงการ\r\n\r\n\r\n-2-\r\n6. งบประมาณ\r\n		ไม่ใช้งบประมาณ\r\n7. การติดตามประเมินผล\r\n		ประเมินจากผลการปฏิบัติงาน และความพึงพอใจของผู้รับบริการ\r\n8. ผลที่คาดว่าจะได้รับ\r\n๑. สามารถพัฒนาทักษะและเสริมสร้างความรู้ความเข้าใจ กับการปฏิบัติงานหน้าบัลลังก์แก่บุคลกรผู้ปฏิบัติงานและผู้ที่เกี่ยวข้อง\r\n๒. บุคลากรสามารถสร้างเสริมระบบการจัดการองค์ความรู้ (Knowledge Management) สามารถนำความรู้มาใช้ในการปฏิบัติงานให้เป็นไปอย่างมีประสิทธิภาพยิ่งขึ้น\r\n9. ผู้รับผิดชอบโครงการ\r\n		ส่วนช่วยพิจารณาคดี ศาลจังหวัดอุดรธานี\r\n\r\n', '3', 'ณ ห้องประชุมศาลจังหวัดอุดรธานี', '6', '2023-06-28', '', '17.00', '20.00', '17', '1', '1', '2023-05-29 16:32:32') ON CONFLICT (id) DO NOTHING;
INSERT INTO _project VALUES (18, 'โครงการ  ร่วมใจให้บริการมุ่งมั่นแบบ SMART TEAM', 'เพื่อเสริมสร้างบุคลิกภาพ', '4', 'ณ ห้องประชุมศาลจังหวัดอุดรธานี', '5', '2023-07-06', '', '13.30', '17.30', '18', '1', '1', '2023-07-06 18:14:04') ON CONFLICT (id) DO NOTHING;
INSERT INTO _project VALUES (19, 'โครงการ  เติมความรู้ เพิ่มทักษะ เสริมสมรรถนะ การปลดทำลายสำนวนความและเอกสาร', 'การพัฒนาบุคลาการให้มีความรู้ ความสามารถ มีทักษะในการปฏิบัติงานให้เป็นไปตามระเบียบแบบแผนที่สำนักงานศาลยุติธรรมกำหนด', '2', 'ณ ห้องประชุมศาลจังหวัดอุดรธานี', '8', '2023-05-03', '', '11.30', '13.30', '19', '1', '1', '2023-07-07 10:33:55') ON CONFLICT (id) DO NOTHING;
INSERT INTO _project VALUES (20, 'โครงการส่งเสริมสุขภาพกายสำหรับข้าราชการฝ่าย ตุลาการศาลยุติธรรมในจังหวัดอุดรธานี เรื่อง “Orthopedics in Daily life…ดูแลกระดูกอย่างไรให้แข็งแรง”', 'ด้วยสำนักงานศาลยุติธรรม โดยสำนักการแพทย์ ได้สนับสนุนงบประมาณการจัดกิจกรรมโครงการส่งเสริมสุขภาพกายสำหรับข้าราชการฝ่ายตุลาการศาลยุติธรรม เรื่อง “Orthopedics in Daily life…ดูแลกระดูกอย่างไรให้แข็งแรง” เพื่อให้ข้าราชการฝ่ายตุลาการศาลยุติธรรมในจังหวัดอุดรธานีมีความรู้ความเข้าใจเกี่ยวกับภาวะของการเกิดโรคออฟฟิศซินโดรม (Office Syndrome) และโรคในทางออร์โธปิดิกส์ (กระดูกและข้อ) ซึ่งจะช่วยป้องกันการเกิดโรคหรือทำให้รักษาได้ง่ายยิ่งขึ้น อันเป็นการพัฒนาคุณภาพชีวิตของบุคลากรในองค์กรศาลยุติธรรม และเพิ่มประสิทธิภาพในการทำงานเพื่อให้บริการประชาชนตามนโยบายประธานศาลฎีกา ข้อ 1 รักศาล โครงการเสริมสร้างคุณภาพชีวิตที่ดีและส่งเสริมสวัสดิการบุคลากรศาลยุติธรรมอย่างสมดุล ทั่วถึง และยั่งยืน สอดคล้องตามแผนยุทธศาสตร์ศาลยุติธรรม พ.ศ. 2565 – 2568 ยุทธศาสตร์ S/(Sustainability) ศาลยุติธรรมมีระบบงานที่มุ่งผลสัมฤทธิ์และผลประโยชน์ส่วนรวมอย่างยั่งยืน', '6', 'ณ ห้องประชุมใหญ่ชั้น 3 ศาลจังหวัดอุดรธานี', '22', '2023-07-14', '', '09.00', '16.00', '20', '1', '1', '2023-07-19 09:58:14') ON CONFLICT (id) DO NOTHING;
